//! Default-model policy over raw public configuration metadata.
use crate::{conversations::Connection, schedule::ModelSelection};
use serde::Deserialize;

#[derive(Clone, Debug, Deserialize)]
pub struct Configuration {
    pub primary: Option<ModelSelection>,
    pub default_connection: Option<i64>,
    pub servers: Vec<Connection>,
}
impl Configuration {
    pub fn default_model(&self) -> Result<ModelSelection, String> {
        let selected = if let Some(primary) = &self.primary {
            primary.clone()
        } else {
            let server = if let Some(id) = self.default_connection {
                self.servers
                    .iter()
                    .find(|server| server.id == id)
                    .ok_or("The default server no longer exists")?
            } else {
                self.servers
                    .iter()
                    .find(|server| server.enabled)
                    .ok_or("Configure a model before scheduling work")?
            };
            ModelSelection {
                server_id: server.id,
                model: server
                    .model
                    .clone()
                    .ok_or("Choose a default model before scheduling work")?,
            }
        };
        if !self
            .servers
            .iter()
            .any(|server| server.id == selected.server_id && server.enabled)
            || selected.model.trim().is_empty()
            || selected.model.len() > 256
            || selected.model.chars().any(char::is_control)
        {
            return Err(
                "Choose an enabled default server and valid model before scheduling work".into(),
            );
        }
        Ok(selected)
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn default_model_priority_is_source_policy_and_reads_current_metadata() {
        let mut config = Configuration {
            primary: None,
            default_connection: None,
            servers: vec![
                Connection {
                    id: 1,
                    model: Some("disabled".into()),
                    enabled: false,
                },
                Connection {
                    id: 2,
                    model: Some("first enabled".into()),
                    enabled: true,
                },
                Connection {
                    id: 3,
                    model: Some("explicit server".into()),
                    enabled: true,
                },
            ],
        };
        assert_eq!(config.default_model().unwrap().model, "first enabled");
        config.default_connection = Some(3);
        assert_eq!(config.default_model().unwrap().model, "explicit server");
        config.primary = Some(ModelSelection {
            server_id: 2,
            model: "configured primary".into(),
        });
        assert_eq!(config.default_model().unwrap().model, "configured primary");
        config.primary.as_mut().unwrap().model = "new primary".into();
        assert_eq!(config.default_model().unwrap().model, "new primary");
        config.servers[1].enabled = false;
        assert!(config.default_model().is_err());
        config.primary = None;
        config.default_connection = Some(99);
        assert!(config.default_model().is_err());
        config.default_connection = Some(3);
        config.servers[2].model = None;
        assert!(config.default_model().is_err());
    }
}

//! Select conversations from scoped SDK metadata; the host does not choose “latest”.
use crate::schedule::{Draft, ModelSelection, SessionTarget};
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Deserialize)]
pub struct Conversation {
    pub id: i64,
    pub value: Metadata,
}
#[derive(Clone, Debug, Deserialize)]
pub struct Metadata {
    #[serde(default)]
    pub origin: bool,
    pub archived: bool,
    pub last_activity: i64,
    pub model_override: Option<SessionModel>,
    pub connection: Option<Connection>,
}
#[derive(Clone, Debug, Deserialize)]
pub struct SessionModel {
    #[serde(alias = "server_id")]
    pub connection_id: i64,
    pub model: String,
}
#[derive(Clone, Debug, Deserialize)]
pub struct Connection {
    pub id: i64,
    pub model: Option<String>,
    pub enabled: bool,
}
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Target {
    Session { id: i64 },
    New { title: String },
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Selection {
    pub target: Target,
    pub model: ModelSelection,
}
/// Call with all pages collected at delivery time, not a snapshot taken at creation.
/// `default_model` must come from current general host configuration metadata.
pub fn select(
    draft: &Draft,
    conversations: &[Conversation],
    default_model: Option<&ModelSelection>,
) -> Result<Selection, String> {
    let conversation = match draft.session_target {
        SessionTarget::Existing => Some(
            conversations
                .iter()
                .find(|row| row.id == draft.session_id)
                .ok_or("The task conversation no longer exists in this project")?,
        ),
        SessionTarget::New => None,
        SessionTarget::Latest => conversations
            .iter()
            .filter(|row| !row.value.archived)
            .max_by_key(|row| (row.value.last_activity, row.id)),
    };
    let target = conversation.map_or_else(
        || Target::New {
            title: draft.title.clone(),
        },
        |row| Target::Session { id: row.id },
    );
    let configured = conversation.and_then(|row| {
        row.value
            .model_override
            .as_ref()
            .map(|selection| ModelSelection {
                server_id: selection.connection_id,
                model: selection.model.clone(),
            })
            .or_else(|| {
                row.value
                    .connection
                    .as_ref()
                    .filter(|connection| connection.enabled)
                    .and_then(|connection| {
                        connection.model.as_ref().map(|model| ModelSelection {
                            server_id: connection.id,
                            model: model.clone(),
                        })
                    })
            })
    });
    let model = draft
        .model
        .clone()
        .or(configured)
        .or_else(|| default_model.cloned())
        .ok_or("Configure a model before scheduling this conversation")?;
    if model.server_id <= 0
        || model.model.trim().is_empty()
        || model.model.len() > 256
        || model.model.chars().any(char::is_control)
    {
        return Err("Choose a valid server and model for this task".into());
    }
    Ok(Selection { target, model })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::schedule::Schedule;
    fn draft(target: SessionTarget) -> Draft {
        Draft {
            session_target: target,
            session_id: 1,
            title: "Task".into(),
            auto_title: false,
            prompt: "Work".into(),
            enabled: true,
            model: None,
            schedule: Schedule::Once { at: 100 },
        }
    }
    fn model(id: i64, name: &str) -> ModelSelection {
        ModelSelection {
            server_id: id,
            model: name.into(),
        }
    }
    fn row(id: i64, activity: i64, archived: bool) -> Conversation {
        Conversation {
            id,
            value: Metadata {
                origin: false,
                archived,
                last_activity: activity,
                model_override: None,
                connection: Some(Connection {
                    id: 9,
                    enabled: true,
                    model: Some("configured".into()),
                }),
            },
        }
    }
    #[test]
    fn latest_excludes_archived_and_breaks_activity_ties_by_id_each_delivery() {
        let mut rows = vec![
            row(1, 10, false),
            row(2, 20, false),
            row(3, 20, false),
            row(4, 99, true),
        ];
        assert_eq!(
            select(&draft(SessionTarget::Latest), &rows, None)
                .unwrap()
                .target,
            Target::Session { id: 3 }
        );
        rows[0].value.last_activity = 100;
        assert_eq!(
            select(&draft(SessionTarget::Latest), &rows, None)
                .unwrap()
                .target,
            Target::Session { id: 1 }
        );
        // An explicit existing conversation may be archived; latest is a different policy.
        rows[0].value.archived = true;
        assert_eq!(
            select(&draft(SessionTarget::Existing), &rows, None)
                .unwrap()
                .target,
            Target::Session { id: 1 }
        );
        assert!(
            select(
                &draft(SessionTarget::Existing),
                &[],
                Some(&model(1, "default"))
            )
            .is_err()
        );
    }
    #[test]
    fn model_precedence_and_empty_latest_fallback_belong_to_source() {
        let mut rows = vec![row(1, 1, false)];
        let mut task = draft(SessionTarget::Existing);
        assert_eq!(
            select(&task, &rows, None).unwrap().model,
            model(9, "configured")
        );
        rows[0].value.model_override = Some(SessionModel {
            connection_id: 8,
            model: "override".into(),
        });
        assert_eq!(
            select(&task, &rows, None).unwrap().model,
            model(8, "override")
        );
        task.model = Some(model(7, "task pin"));
        assert_eq!(
            select(&task, &rows, None).unwrap().model,
            model(7, "task pin")
        );
        task.model = None;
        rows[0].value.model_override = None;
        rows[0].value.connection.as_mut().unwrap().enabled = false;
        assert_eq!(
            select(&task, &rows, Some(&model(6, "current default")))
                .unwrap()
                .model,
            model(6, "current default")
        );
        assert!(select(&task, &rows, None).is_err());
        let selection = select(
            &draft(SessionTarget::Latest),
            &[],
            Some(&model(5, "new default")),
        )
        .unwrap();
        assert_eq!(
            selection.target,
            Target::New {
                title: "Task".into()
            }
        );
        assert_eq!(selection.model, model(5, "new default"));
        task.model = Some(model(1, "\n"));
        assert!(select(&task, &rows, None).is_err());
    }

    #[test]
    fn sdk_metadata_decodes_the_apps_connection_id_override_shape() {
        let rows: Vec<Conversation> = openwebide_plugin_sdk::serde_json::from_value(
            openwebide_plugin_sdk::serde_json::json!([{"id":1,"revision":2,"value":{
                "origin":true,"archived":false,"last_activity":10,
                "model_override":{"connection_id":8,"model":"session override"},
                "connection":{"id":9,"model":"server default","enabled":true}
            }}]),
        )
        .unwrap();
        assert!(rows[0].value.origin);
        assert_eq!(
            select(&draft(SessionTarget::Existing), &rows, None)
                .unwrap()
                .model,
            model(8, "session override")
        );
    }
}

//! Host-executed Scheduling behavior using only the public SDK.
pub mod configuration;
pub mod conversations;
pub mod schedule;
pub mod service;
use openwebide_plugin_sdk::{
    EventInput, Outcome, Plugin, Tool,
    serde_json::{self, Value},
};

pub struct SchedulingPlugin;
impl Plugin for SchedulingPlugin {
    fn tools() -> Vec<Tool> {
        let manifest: Value =
            serde_json::from_str(include_str!("../plugin.json")).expect("embedded manifest");
        serde_json::from_value(manifest["contributions"]["tools"].clone())
            .expect("declared tool schemas")
    }
    fn events() -> Vec<String> {
        vec![
            "task_due".into(),
            "task_completed".into(),
            "reconcile".into(),
        ]
    }
    fn execute(name: &str, arguments: Value) -> Result<Outcome, String> {
        service::execute(&mut service::SdkHost, name, arguments)
    }
    fn event(input: EventInput) -> Result<Outcome, String> {
        match input.name.as_str() {
            "task_due" => service::due(
                &mut service::SdkHost,
                serde_json::from_value(input.payload).map_err(|error| error.to_string())?,
            ),
            "task_completed" => service::completed(
                &mut service::SdkHost,
                serde_json::from_value(input.payload).map_err(|error| error.to_string())?,
            ),
            "reconcile" if input.payload.is_null() => service::reconcile(&mut service::SdkHost),
            _ => Err("Unknown scheduling event".into()),
        }
    }
}
openwebide_plugin_sdk::export!(SchedulingPlugin);

//! Cron/timezone validation and recurrence are plugin behavior, not host callbacks.
use chrono::{DateTime, Utc};
use chrono_tz::Tz;
use serde::{Deserialize, Serialize};
use std::str::FromStr;

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ModelSelection {
    pub server_id: i64,
    pub model: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum Schedule {
    Once {
        at: i64,
    },
    Cron {
        expression: String,
        timezone: String,
    },
}
impl Schedule {
    pub fn next_after(&self, after: i64) -> Result<Option<i64>, String> {
        match self {
            Self::Once { at } => Ok((*at > after).then_some(*at)),
            Self::Cron {
                expression,
                timezone,
            } => {
                if expression.len() > 128 || expression.split_whitespace().count() != 5 {
                    return Err(
                        "Use a five-field cron expression (minute hour day month weekday).".into(),
                    );
                }
                let zone = Tz::from_str(timezone).map_err(|_| "Choose a valid timezone.")?;
                let start = DateTime::<Utc>::from_timestamp(after, 0)
                    .ok_or("Invalid schedule timestamp.")?
                    .with_timezone(&zone);
                let cron = croner::Cron::from_str(expression)
                    .map_err(|error| format!("Invalid schedule: {error}"))?;
                let next = cron
                    .find_next_occurrence(&start, false)
                    .map_err(|error| format!("Schedule has no next occurrence: {error}"))?;
                Ok(Some(next.timestamp()))
            }
        }
    }
    pub fn validate(&self, now: i64) -> Result<(), String> {
        if self.next_after(now)?.is_none() {
            return Err("Choose a future date and time.".into());
        }
        Ok(())
    }
}
/// Session policy is resolved when an occurrence becomes due, not when saved.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SessionTarget {
    #[default]
    Existing,
    New,
    Latest,
}
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Draft {
    #[serde(default)]
    pub session_target: SessionTarget,
    #[serde(default)]
    pub auto_title: bool,
    #[serde(default)]
    pub title: String,
    pub prompt: String,
    #[serde(default)]
    pub session_id: i64,
    /// None resolves the session’s current model when the task runs.
    #[serde(default)]
    pub model: Option<ModelSelection>,
    pub schedule: Schedule,
    pub enabled: bool,
}
impl Draft {
    pub fn validate(&self, now: i64) -> Result<(), String> {
        if (!self.auto_title && self.title.trim().is_empty()) || self.title.chars().count() > 120 {
            return Err("Task titles need 1–120 characters.".into());
        }
        if self.prompt.trim().is_empty() || self.prompt.len() > 32 * 1024 {
            return Err("Task prompts need 1–32 KiB of text.".into());
        }
        if self.session_target == SessionTarget::Existing && self.session_id <= 0 {
            return Err("Choose a session for this task.".into());
        }
        if let Some(model) = &self.model
            && (model.server_id <= 0
                || model.model.trim().is_empty()
                || model.model.len() > 256
                || model.model.chars().any(char::is_control))
        {
            return Err("Choose a valid server and model for this task.".into());
        }
        if let Schedule::Once { at } = self.schedule
            && at < 0
        {
            return Err("Invalid schedule timestamp".into());
        }
        if self.enabled {
            self.schedule.validate(now)
        } else {
            self.schedule.next_after(now).map(|_| ())
        }
    }
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MonitorStart {
    pub prompt: String,
    pub delay_seconds: i64,
    #[serde(default = "interval")]
    pub interval_seconds: i64,
    #[serde(default = "checks")]
    pub max_checks: i64,
}
const fn interval() -> i64 {
    600
}
const fn checks() -> i64 {
    1
}
impl MonitorStart {
    pub fn draft(&self, session: i64, now: i64) -> Result<(Draft, i64), String> {
        if !(5..86400).contains(&self.delay_seconds)
            || !(5..=86400).contains(&self.interval_seconds)
            || !(1..=24).contains(&self.max_checks)
            || self
                .delay_seconds
                .saturating_add(self.interval_seconds.saturating_mul(self.max_checks - 1))
                >= 86400
        {
            return Err("Monitor checks must fit within 24 hours with delays of 5–86399 seconds, intervals of 5–86400 seconds and 1–24 checks".into());
        }
        if now < 0 {
            return Err("Invalid clock".into());
        }
        let expires = now.checked_add(86400).ok_or("Invalid expiry")?;
        let draft = Draft {
            session_target: SessionTarget::Existing,
            auto_title: false,
            title: "Monitor".into(),
            prompt: self.prompt.clone(),
            session_id: session,
            model: None,
            schedule: Schedule::Once {
                at: now
                    .checked_add(self.delay_seconds)
                    .ok_or("Invalid monitor timestamp")?,
            },
            enabled: true,
        };
        draft.validate(now)?;
        Ok((draft, expires))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    fn stamp(value: &str) -> i64 {
        DateTime::parse_from_rfc3339(value).unwrap().timestamp()
    }
    #[test]
