        };
        assert_eq!(
            schedule.next_after(stamp("2026-03-07T16:00:00Z")).unwrap(),
            Some(stamp("2026-03-08T14:00:00Z"))
        );
        assert_eq!(
            schedule.next_after(stamp("2026-10-31T15:00:00Z")).unwrap(),
            Some(stamp("2026-11-01T15:00:00Z"))
        );
    }
