        assert_eq!(Schedule::Once { at: 100 }.next_after(100).unwrap(), None);
        assert!(Schedule::Once { at: 100 }.validate(100).is_err());
        for (expression, timezone) in [
            ("* * * * * *", "UTC"),
            ("0 9 * * *", "Mars/Base"),
            ("99 9 * * *", "UTC"),
        ] {
            assert!(
                Schedule::Cron {
                    expression: expression.into(),
                    timezone: timezone.into()
                }
                .validate(0)
                .is_err()
            );
        }
