        assert_eq!(expiry, 86500);
        assert_eq!(draft.schedule, Schedule::Once { at: 105 });
        for (delay, interval, checks) in [
            (4, 600, 1),
            (86400, 600, 1),
            (5, 4, 1),
            (5, 600, 25),
            (86399, 600, 2),
        ] {
            start.delay_seconds = delay;
