#[derive(Deserialize)]
struct Page<T> {
    records: Vec<T>,
    next: Option<i64>,
}
fn clock(host: &mut impl Host) -> Result<i64, String> {
    host.call("clock", json!({}))?["unix_seconds"]
        .as_i64()
        .filter(|now| *now >= 0)
        .ok_or("Invalid host clock".into())
}
fn collection(host: &mut impl Host, name: &str, operation: Value) -> Result<Value, String> {
    host.call(
        "collections",
        json!({"collection":name,"operation":operation}),
    )
}
fn all<T: serde::de::DeserializeOwned>(host: &mut impl Host, name: &str) -> Result<Vec<T>, String> {
    let mut result = Vec::new();
    let mut after = 0;
    for _ in 0..64 {
        let page: Page<T> = serde_json::from_value(collection(
            host,
            name,
            json!({"action":"list","after":after}),
        )?)
        .map_err(|error| error.to_string())?;
        result.extend(page.records);
        match page.next {
            Some(next) if next > after => after = next,
            None => return Ok(result),
            _ => return Err("Invalid collection cursor".into()),
        }
    }
    Err("Collection traversal exceeded its bounded page budget".into())
}
fn tasks(host: &mut impl Host) -> Result<Vec<Task>, String> {
    all::<Value>(host, "tasks")?
        .into_iter()
        .filter(|row| row["value"]["editable"].as_bool() != Some(false))
        .map(|mut row| {
            if row["value"]["state"].is_null() {
                row["value"]["state"] = json!({});
            }
            serde_json::from_value(row).map_err(|error| error.to_string())
        })
        .collect()
}
fn task(host: &mut impl Host, id: i64) -> Result<Task, String> {
    tasks(host)?
        .into_iter()
        .find(|task| task.id == id)
        .ok_or("Task not found or owned by another plugin".into())
}

fn save(host: &mut impl Host, previous: Option<&Task>, value: TaskValue) -> Result<Task, String> {
    let operation = previous.map_or_else(
        || json!({"action":"create","value":value}),
        |record| json!({"action":"update","id":record.id,"revision":record.revision,"value":value}),
    );
    let mut page: Page<Task> = serde_json::from_value(collection(host, "tasks", operation)?)
        .map_err(|error| error.to_string())?;
    if page.records.len() != 1 {
        return Err("Task mutation returned no record".into());
    }
    Ok(page.records.remove(0))
}
fn origin(rows: &[Conversation], session: i64) -> Result<i64, String> {
    rows.iter()
        .find(|row| {
            if session > 0 {
                row.id == session
            } else {
                row.value.origin
            }
        })
        .map(|row| row.id)
        .ok_or("Choose a conversation in this project".into())
}
fn named(host: &mut impl Host, mut draft: Draft, now: i64) -> Result<Draft, String> {
    if draft.session_target == SessionTarget::Existing {
        draft.session_id = origin(&all(host, "conversations")?, draft.session_id)?;
    }
    if draft.title.trim().is_empty() {
        draft.auto_title = true;
    }
    draft.validate(now)?;
    if draft.auto_title {
        let fallback = draft
            .prompt
            .split_whitespace()
            .collect::<Vec<_>>()
            .join(" ")
            .chars()
            .take(80)
            .collect::<String>();
        let mut title = None;
        for profile in ["fast", "primary"] {
            if let Ok(value)=host.call("completion",json!({"system_prompt":"Name this scheduled task in at most eight words. Return only a plain title, without quotes or punctuation wrapping.","prompt":draft.prompt,"profile":profile,"max_output_tokens":64})) {
                let text=value["text"].as_str().unwrap_or("").trim().trim_matches('"').trim();
                if !text.is_empty() && text.chars().count()<=120 && !text.chars().any(char::is_control) {title=Some(text.to_owned());break;}
            }
        }
        draft.title = title.unwrap_or(fallback);
    }
    Ok(draft)
}
fn arm(host: &mut impl Host, task: &Task) -> Result<(), String> {
    let Some(due) = task.value.next_run.filter(|_| task.value.draft.enabled) else {
        return Ok(());
    };
    host.call("jobs",json!({"action":"schedule","key":format!("task:{}:{}:{due}",task.id,task.value.state.generation),
        "scope":"project","due_at":due,
        "expires_at":task.value.monitor.as_ref().map(|monitor|monitor.expires_at),
        "event":"task_due","payload":{"task_id":task.id,"generation":task.value.state.generation,"due_at":due}}))?;
    Ok(())
}
/// Invalidate the task generation before calling this; old actors cannot queue new work.
fn cancel_work(host: &mut impl Host, id: i64) -> Result<(), String> {
    let prefix = format!("task:{id}:");
    for (capability, field, cursor) in [
        ("jobs", "jobs", "next_after"),
        ("runs", "runs", "next_after"),
    ] {
        let mut after = 0;
        for page_index in 0..64 {
            let page = host.call(capability, json!({"action":"list","after":after}))?;
            for record in page[field].as_array().ok_or("Invalid work page")? {
                let key = record["key"].as_str().ok_or("Invalid work key")?;
                let state = record["state"].as_str().ok_or("Invalid work state")?;
                if key.starts_with(&prefix)
                    && matches!(
                        state,
                        "pending" | "leased" | "running" | "blocked" | "waiting"
                    )
                {
                    host.call(
                        capability,
                        json!({"action":"cancel","id":record["id"],"revision":record["revision"]}),
                    )?;
                }
            }
            match page[cursor].as_i64() {
                Some(next) if next > after => after = next,
                None => break,
                _ => return Err("Invalid work cursor".into()),
            }
            if page_index == 63 {
                return Err("Work traversal exceeded its bounded page budget".into());
            }
        }
    }
    Ok(())
}
fn excerpt(task: &Task) -> Value {
    json!({"id":task.id,"revision":task.revision,"title":task.value.draft.title,
        "prompt_excerpt":task.value.draft.prompt.chars().take(256).collect::<String>(),
        "session_id":task.value.draft.session_id,"session_target":task.value.draft.session_target,
        "schedule":task.value.draft.schedule,"enabled":task.value.draft.enabled,
        "next_run":task.value.next_run,"last_run":task.value.state.last_result})
}
#[derive(Deserialize)]
#[serde(tag = "action", rename_all = "snake_case", deny_unknown_fields)]
enum Command {
    List,
    Create {
        draft: Draft,
    },
    Update {
        id: i64,
        revision: i64,
        draft: Draft,
    },
    SetEnabled {
        id: i64,
        revision: i64,
        enabled: bool,
    },
    Delete {
        id: i64,
        revision: i64,
    },
}
#[derive(Deserialize)]
#[serde(tag = "action", rename_all = "snake_case", deny_unknown_fields)]
enum MonitorCommand {
    Start {
        prompt: String,
        delay_seconds: i64,
        #[serde(default = "interval")]
        interval_seconds: i64,
        #[serde(default = "checks")]
        max_checks: i64,
        #[serde(default)]
        session_id: i64,
    },
    List {
        #[serde(default)]
        session_id: i64,
    },
    Cancel {
        id: i64,
        revision: i64,
        #[serde(default)]
        session_id: i64,
    },
}
const fn interval() -> i64 {
    600
}
const fn checks() -> i64 {
    1
}
fn outcome(value: Value, summary: &str) -> Outcome {
    Outcome {
        ok: true,
        content: value.to_string(),
        summary: summary.into(),
    }
}
fn create(
    host: &mut impl Host,
    draft: Draft,
    monitor: Option<Monitor>,
    now: i64,
) -> Result<Task, String> {
    let count = tasks(host)?
        .iter()
        .filter(|task| task.value.monitor.is_some() == monitor.is_some())
        .count();
    if count >= if monitor.is_some() { 20 } else { 100 } {
        return Err(
            "This scope has reached its task limit (20 monitors or 100 saved tasks)".into(),
        );
    }
    let next_run = if draft.enabled {
        draft.schedule.next_after(now)?
    } else {
        None
    };
    let created = save(
        host,
        None,
        TaskValue {
            draft,
            next_run,
            monitor,
            state: State {
                generation: 1,
                source_version: env!("CARGO_PKG_VERSION").into(),
                ..State::default()
            },
        },
    )?;
    if let Err(error) = arm(host, &created) {
        collection(
            host,
            "tasks",
            json!({"action":"delete","id":created.id,"revision":created.revision}),
        )?;
        return Err(error);
    }
    Ok(created)
}
pub fn execute(host: &mut impl Host, name: &str, mut arguments: Value) -> Result<Outcome, String> {
    if name == "monitor" {
        let command: MonitorCommand =
            serde_json::from_value(arguments).map_err(|error| error.to_string())?;
        let now = clock(host)?;
        return match command {
            MonitorCommand::Start {
                prompt,
                delay_seconds,
                interval_seconds,
                max_checks,
                session_id,
            } => {
                let rows = all::<Conversation>(host, "conversations")?;
                let session = origin(&rows, session_id)?;
                let monitored = tasks(host)?
                    .into_iter()
                    .filter(|task| {
                        task.value
                            .monitor
                            .as_ref()
                            .is_some_and(|monitor| monitor.session_id == session)
                    })
                    .map(|task| task.id)
                    .collect::<Vec<_>>();
                let mut after = 0;
                for page_index in 0..64 {
                    let page = host.call("runs", json!({"action":"list","after":after}))?;
                    if page["runs"]
                        .as_array()
                        .ok_or("Invalid run page")?
                        .iter()
                        .any(|run| {
                            run["session_id"].as_i64() == Some(session)
                                && matches!(run["state"].as_str(), Some("running" | "blocked"))
                                && run["key"].as_str().is_some_and(|key| {
                                    monitored
                                        .iter()
                                        .any(|id| key.starts_with(&format!("task:{id}:")))
                                })
                        })
                    {
                        return Err("A monitor check cannot start another monitor to extend its deadline; configure bounded repeats when starting it".into());
                    }
                    match page["next_after"].as_i64() {
                        Some(next) if next > after => after = next,
                        None => break,
                        _ => return Err("Invalid run cursor".into()),
                    }
                    if page_index == 63 {
                        return Err("Run traversal exceeded its bounded page budget".into());
                    }
                }
                let (draft, expires) = MonitorStart {
                    prompt,
                    delay_seconds,
                    interval_seconds,
                    max_checks,
                }
                .draft(session, now)?;
                let monitor = Monitor {
                    session_id: session,
                    interval_seconds,
                    remaining: max_checks,
                    expires_at: expires,
                };
                let saved = create(host, draft, Some(monitor), now)?;
                Ok(outcome(json!([excerpt(&saved)]), "Monitor started"))
            }
            MonitorCommand::List { session_id } => {
                let session = origin(&all(host, "conversations")?, session_id)?;
                let records = tasks(host)?;
                Ok(outcome(
                    json!(
                        records
                            .iter()
                            .filter(|task| task.value.draft.enabled
                                && task
                                    .value
                                    .monitor
                                    .as_ref()
                                    .is_some_and(|monitor| monitor.session_id == session
                                        && monitor.expires_at > now))
                            .map(excerpt)
                            .collect::<Vec<_>>()
                    ),
                    "Monitors listed",
                ))
            }
            MonitorCommand::Cancel {
                id,
                revision,
                session_id,
            } => {
                if session_id != 0
                    && !task(host, id)?
                        .value
                        .monitor
                        .is_some_and(|monitor| monitor.session_id == session_id)
                {
                    return Err("Monitor belongs to another conversation".into());
                }
                remove(host, id, revision, true)?;
                Ok(outcome(json!([]), "Monitor cancelled"))
            }
        };
    }
    let action = match name {
        "schedule_list" => "list",
        "schedule_create" => "create",
        "schedule_update" => "update",
        "schedule_delete" => "delete",
        "schedule_set_enabled" => "set_enabled",
        _ => return Err("Unknown scheduling tool".into()),
    };
    let args = arguments
        .as_object_mut()
        .ok_or("Expected an argument object")?;
    if args.contains_key("action") {
        return Err("Unexpected action argument".into());
    }
    args.insert("action".into(), json!(action));
    let command: Command = serde_json::from_value(arguments).map_err(|error| error.to_string())?;
    let now = clock(host)?;
    match command {
        Command::List => Ok(outcome(
            json!(
                tasks(host)?
                    .iter()
                    .filter(|task| task.value.monitor.is_none())
                    .map(excerpt)
                    .collect::<Vec<_>>()
            ),
            "Tasks listed",
        )),
        Command::Create { draft } => {
            let draft = named(host, draft, now)?;
            let saved = create(host, draft, None, now)?;
            Ok(outcome(json!([excerpt(&saved)]), "Task created"))
        }
        Command::Update {
            id,
            revision,
            draft,
        } => {
            let old = task(host, id)?;
            if old.revision != revision || old.value.monitor.is_some() {
                return Err("Saved task revision changed".into());
            }
            let draft = named(host, draft, now)?;
            let next_run = if draft.enabled {
                draft.schedule.next_after(now)?
            } else {
                None
            };
            let generation = old
                .value
                .state
                .generation
                .checked_add(1)
                .ok_or("Task generation exhausted")?;
            let saved = save(
                host,
                Some(&old),
                TaskValue {
                    draft,
                    next_run,
                    monitor: None,
                    state: State {
                        generation,
                        source_version: env!("CARGO_PKG_VERSION").into(),
                        deleting: false,
                        last_result: old.value.state.last_result.clone(),
                        preflight: old.value.state.preflight.clone(),
                        pending: vec![],
                    },
                },
            )?;
            cancel_work(host, id)?;
            arm(host, &saved)?;
            Ok(outcome(json!([excerpt(&saved)]), "Task updated"))
        }
        Command::SetEnabled {
            id,
            revision,
            enabled,
        } => {
            let old = task(host, id)?;
            if old.revision != revision || old.value.monitor.is_some() {
                return Err("Saved task revision changed".into());
            }
            let mut value = old.value.clone();
            value.draft.enabled = enabled;
            value.next_run =
                if enabled {
                    Some(
                        value.draft.schedule.next_after(now)?.ok_or(
                            "This one-time task has already passed. Edit its date to resume.",
                        )?,
                    )
                } else {
                    None
                };
            value.state.generation = value
                .state
                .generation
                .checked_add(1)
                .ok_or("Task generation exhausted")?;
            value.state.source_version = env!("CARGO_PKG_VERSION").into();
            value.state.pending.clear();
            let saved = save(host, Some(&old), value)?;
            cancel_work(host, id)?;
            arm(host, &saved)?;
            Ok(outcome(
                json!([excerpt(&saved)]),
                if enabled {
                    "Task resumed"
                } else {
                    "Task paused"
                },
            ))
        }
        Command::Delete { id, revision } => {
            remove(host, id, revision, false)?;
            Ok(outcome(json!([]), "Task deleted"))
        }
    }
}
fn remove(host: &mut impl Host, id: i64, revision: i64, monitor: bool) -> Result<(), String> {
    let old = task(host, id)?;
    if old.revision != revision || old.value.monitor.is_some() != monitor {
        return Err("Task revision or type changed".into());
    }
    let mut value = old.value.clone();
    value.draft.enabled = false;
    value.next_run = None;
    value.state.generation = value
        .state
        .generation
        .checked_add(1)
        .ok_or("Task generation exhausted")?;
    value.state.pending.clear();
    value.state.deleting = true;
    let invalidated = save(host, Some(&old), value)?;
    cancel_work(host, id)?;
    collection(
        host,
        "tasks",
        json!({"action":"delete","id":id,"revision":invalidated.revision}),
    )?;
    Ok(())
}
#[derive(Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Due {
    pub task_id: i64,
    pub generation: u64,
    pub due_at: i64,
}
fn work(host: &mut impl Host, capability: &str) -> Result<Vec<Value>, String> {
    let field = if capability == "jobs" { "jobs" } else { "runs" };
    let mut records = Vec::new();
    let mut after = 0;
    for _ in 0..64 {
        let page = host.call(capability, json!({"action":"list","after":after}))?;
        records.extend(
            page[field]
                .as_array()
                .ok_or("Invalid work page")?
                .iter()
                .cloned(),
        );
        match page["next_after"].as_i64() {
            Some(next) if next > after => after = next,
            None => return Ok(records),
            _ => return Err("Invalid work cursor".into()),
        }
    }
    Err("Work traversal exceeded its bounded page budget".into())
}
fn occurrence(key: &str) -> Option<Due> {
    let mut parts = key.split(':');
    if parts.next()? != "task" {
        return None;
    }
    let due = Due {
        task_id: parts.next()?.parse().ok()?,
        generation: parts.next()?.parse().ok()?,
        due_at: parts.next()?.parse().ok()?,
    };
    (parts.next().is_none() && due.task_id > 0 && due.due_at >= 0).then_some(due)
}

/// Rebuild durable timers and occurrence state after dropped actors or source updates.
/// Each repair uses normal revision checks. A racing edit is retried on the next tick.
struct RecoveryHost<'a, H: Host> {
    host: &'a mut H,
    remaining: usize,
}
impl<H: Host> Host for RecoveryHost<'_, H> {
    fn call(&mut self, capability: &str, request: Value) -> Result<Value, String> {
        if self.remaining == 0 {
            return Err("Recovery host-call budget exhausted; retry on the next tick".into());
        }
        self.remaining -= 1;
        self.host.call(capability, request)
    }
}
fn recovery_record(host: &mut impl Host, operation: Value) -> Result<Value, String> {
    host.call(
        "records",
        json!({"collection":"recovery","operation":operation}),
    )
}
const RETAINED_HISTORY: usize = 128;
#[derive(Clone, Debug, Default, Serialize, Deserialize)]
struct HistoryRetention {
    #[serde(default)]
    after: i64,
    #[serde(default)]
    recent: Vec<i64>,
}
#[derive(Clone, Debug, Default, Serialize, Deserialize)]
struct CleanupProgress {
    #[serde(default)]
    jobs: i64,
    #[serde(default)]
    runs: i64,
}
#[derive(Default)]
struct CleanupResult {
    errors: Vec<String>,
    jobs: Vec<i64>,
    runs: Vec<i64>,
}
fn result_pending(task: &Task, run: i64, due: &Due) -> bool {
    task.value
        .state
        .pending
        .iter()
        .any(|pending| pending.id == run)
        || (task.value.draft.enabled
            && task.value.state.generation == due.generation
            && task.value.next_run == Some(due.due_at))
}
fn terminal_run(record: &Value) -> bool {
    matches!(
        record["state"].as_str(),
        Some("completed" | "failed" | "cancelled" | "interrupted")
    )
}
fn terminal_job(record: &Value) -> bool {
    matches!(
        record["state"].as_str(),
        Some("completed" | "failed" | "cancelled" | "expired")
    )
}
/// Return the retained run (if any) that must be saved before freeing this event.
fn cleanup_job<'a>(
    job: &'a Value,
    tasks: &[Task],
    runs: &'a [Value],
) -> Option<(i64, Due, Option<&'a Value>)> {
    if !terminal_job(job) {
        return None;
    }
    if job["event"] == "task_due" {
        let due = occurrence(job["key"].as_str()?)?;
        let needed = tasks
            .iter()
            .find(|task| task.id == due.task_id)
            .is_some_and(|task| {
                task.value.draft.enabled
                    && task.value.state.generation == due.generation
                    && task.value.next_run == Some(due.due_at)
            });
        return (!needed).then_some((0, due, None));
    }
    if job["event"] != "task_completed" {
        return None;
    }
    let run_id: i64 = job["key"].as_str()?.strip_prefix("$run:")?.parse().ok()?;
    if run_id <= 0 {
        return None;
    }
    let payload = &job["payload"];
    let (due, run) = if let Some(key) = payload["run"]["key"].as_str() {
        let due = occurrence(key)?;
        if payload["run"]["id"].as_i64() != Some(run_id)
            || !terminal_run(&payload["run"])
            || payload["data"]["task_id"].as_i64() != Some(due.task_id)
            || payload["data"]["generation"].as_u64() != Some(due.generation)
            || payload["data"]["due_at"].as_i64() != Some(due.due_at)
        {
            return None;
        }
        (due, Some(&payload["run"]))
    } else {
        // A cancelled waiting callback may never have received a terminal snapshot.
        if !matches!(job["state"].as_str(), Some("cancelled" | "expired")) {
            return None;
        }
        let due: Due = serde_json::from_value(payload.clone()).ok()?;
        if due.task_id <= 0 || due.due_at < 0 {
            return None;
        }
        let run = runs.iter().find(|run| run["id"].as_i64() == Some(run_id));
        if let Some(run) = run
            && (!terminal_run(run)
                || run["key"]
                    .as_str()
                    .and_then(occurrence)
                    .is_none_or(|actual| {
                        actual.task_id != due.task_id
                            || actual.generation != due.generation
                            || actual.due_at != due.due_at
                    }))
        {
            return None;
        }
        (due, run)
    };
    let task = tasks.iter().find(|task| task.id == due.task_id);
    if task.is_some_and(|task| result_pending(task, run_id, &due)) {
        return None;
    }
    Some((run_id, due, task.and(run)))
}
fn cleanup_work(
    host: &mut RecoveryHost<'_, impl Host>,
    progress: &mut CleanupProgress,
    tasks: &[Task],
    runs: &[Value],
    jobs: &[Value],
) -> CleanupResult {
    let mut result = CleanupResult::default();
    for (capability, records, cursor) in [
        ("jobs", jobs, &mut progress.jobs),
        ("runs", runs, &mut progress.runs),
    ] {
        let ordered = records
            .iter()
            .filter(|record| record["id"].as_i64().is_some_and(|id| id > *cursor))
            .chain(
                records
                    .iter()
                    .filter(|record| record["id"].as_i64().is_some_and(|id| id <= *cursor)),
            );
        let mut attempts = 0;
        let mut after = *cursor;
        for record in ordered {
            if attempts == 2 || host.remaining < 2 {
                break;
            }
            let Some(id) = record["id"].as_i64().filter(|id| *id > 0) else {
                continue;
            };
            let candidate = if capability == "jobs" {
                cleanup_job(record, tasks, runs)
            } else {
                record["key"]
                    .as_str()
                    .and_then(occurrence)
                    .filter(|due| {
                        terminal_run(record)
                            && !tasks
                                .iter()
                                .find(|task| task.id == due.task_id)
                                .is_some_and(|task| result_pending(task, id, due))
                    })
                    .map(|due| {
                        let snapshot = tasks
                            .iter()
                            .any(|task| task.id == due.task_id)
                            .then_some(record);
                        (id, due, snapshot)
                    })
            };
            let Some((_, due, snapshot)) = candidate else {
                continue;
            };
            attempts += 1;
            let deleted = (|| {
                if let Some(snapshot) = snapshot {
                    record_history(host, due.task_id, due.due_at, snapshot)?;
                }
                host.call(
                    capability,
                    json!({"action":"delete","id":id,"revision":record["revision"]}),
                )?;
                Ok::<_, String>(())
            })();
            if let Err(error) = deleted {
                result.errors.push(error);
                if host.remaining == 0 {
                    break;
                }
            } else if capability == "jobs" {
                result.jobs.push(id);
            } else {
                result.runs.push(id);
            }
            after = id;
        }
        *cursor = after;
    }
    result
}
fn retained_result(record: &Value, tasks: &[Task]) -> bool {
    let value = &record["value"];
    tasks
        .iter()
        .find(|task| Some(task.id) == value["task_id"].as_i64())
        .and_then(|task| task.value.state.last_result.as_ref())
        .is_some_and(|result| {
            (value["run_id"].as_i64().is_some() && value["run_id"] == result["id"])
                || (value["key"].as_str().is_some() && value["key"] == result["key"])
        })
}
fn terminal_history(record: &Value) -> bool {
    record["value"]["editable"] == true
        && matches!(
            record["value"]["snapshot"]["status"].as_str(),
            Some("complete" | "failed" | "cancelled" | "expired" | "interrupted")
        )
}
/// One page and at most three removals per tick; progress survives interrupted scans.
fn retain_history(
    host: &mut RecoveryHost<'_, impl Host>,
    state: &mut HistoryRetention,
    tasks: &[Task],
) -> Result<(), String> {
    if state.after < 0
        || state.recent.len() > RETAINED_HISTORY
        || state.recent.iter().any(|id| *id <= 0)
        || state.recent.windows(2).any(|pair| pair[0] >= pair[1])
    {
        return Err("Invalid history retention cursor".into());
    }
    if host.remaining < 7 {
        return Ok(());
    }
    let page = collection(
        host,
        "task_runs",
        json!({"action":"list","after":state.after}),
    )?;
    let records = page["records"].as_array().ok_or("Invalid history page")?;
    let mut removed = 0;
    for record in records {
        let id = record["id"]
            .as_i64()
            .filter(|id| *id > state.after)
            .ok_or("Invalid history identity")?;
        if terminal_history(record)
            && !retained_result(record, tasks)
            && !state.recent.contains(&id)
        {
            let mut recent = state.recent.clone();
            recent.push(id);
            recent.sort_unstable();
            if recent.len() > RETAINED_HISTORY {
                if removed == 3 {
                    return Ok(());
                }
                let oldest = recent[0];
                // Listing from the preceding ID distinguishes an externally deleted row
                // without classifying SDK errors by their text. It also refreshes revisions.
                let current =
                    collection(host, "task_runs", json!({"action":"list","after":oldest-1}))?;
                if let Some(old) = current["records"]
                    .as_array()
                    .ok_or("Invalid history page")?
                    .first()
                    && old["id"].as_i64() == Some(oldest)
                    && terminal_history(old)
                    && !retained_result(old, tasks)
                {
                    collection(
                        host,
                        "task_runs",
                        json!({"action":"delete","id":oldest,"revision":old["revision"]}),
                    )?;
                }
                recent.remove(0);
                removed += 1;
            }
            state.recent = recent;
        }
        state.after = id;
    }
    if page["next"].is_null() {
        state.after = 0;
    }
    Ok(())
}
pub fn reconcile(host: &mut impl Host) -> Result<Outcome, String> {
    let now = clock(host)?;
    let records = recovery_record(host, json!({"action":"list","after":0}))?;
    let previous = records["records"]
        .as_array()
        .ok_or("Invalid recovery records")?
        .first()
        .cloned();
    let after = previous
        .as_ref()
        .and_then(|record| record["value"]["after"].as_i64())
        .unwrap_or(0);
    let mut host = RecoveryHost {
        host,
        remaining: 110,
    };
    let mut history: HistoryRetention = previous
        .as_ref()
        .and_then(|record| record["value"].get("history"))
        .map(|value| serde_json::from_value(value.clone()))
        .transpose()
        .map_err(|error| error.to_string())?
        .unwrap_or_default();
    let tasks = tasks(&mut host)?;
    let mut cleanup: CleanupProgress = previous
        .as_ref()
        .and_then(|record| record["value"].get("cleanup"))
        .map(|value| serde_json::from_value(value.clone()))
        .transpose()
        .map_err(|error| error.to_string())?
        .unwrap_or_default();
    let mut errors = Vec::new();
    if let Err(error) = retain_history(&mut host, &mut history, &tasks) {
        errors.push(error);
    }
    let mut runs = work(&mut host, "runs")?;
    let mut jobs = work(&mut host, "jobs")?;
    let cleaned = cleanup_work(&mut host, &mut cleanup, &tasks, &runs, &jobs);
    errors.extend(cleaned.errors);
    runs.retain(|record| {
        !record["id"]
            .as_i64()
            .is_some_and(|id| cleaned.runs.contains(&id))
    });
    jobs.retain(|record| {
        !record["id"]
            .as_i64()
            .is_some_and(|id| cleaned.jobs.contains(&id))
    });
    // Visit every record fairly, independent of creation order or permanently failing records.
    let ordered = tasks
        .iter()
        .filter(|task| task.id > after)
        .chain(tasks.iter().filter(|task| task.id <= after));
    let mut repaired = 0;
    let mut attempted = 0;
    let mut cursor = after;
    for old in ordered.take(8) {
        if host.remaining == 0 {
            break;
        }
        attempted += 1;
        match reconcile_task(&mut host, old.clone(), now, &runs, &jobs) {
            Ok(()) => {
                repaired += 1;
                cursor = old.id;
            }
            Err(error) => {
                errors.push(error);
                // Budget exhaustion may have made partial progress; continue this record next tick.
                if host.remaining == 0 {
                    break;
                }
                cursor = old.id;
            }
        }
    }
    let value = json!({"after":cursor,"history":history,"cleanup":cleanup});
    let operation = previous.map_or_else(||json!({"action":"create","value":value}),|record|json!({"action":"update","id":record["id"],"revision":record["revision"],"value":value}));
    // Reserve the cursor write outside the work budget (total remains below 128 host calls).
    recovery_record(host.host, operation)?;
    Ok(Outcome {
        ok: errors.is_empty(),
        content: json!({"reconciled":repaired,"attempted":attempted,"errors":errors}).to_string(),
        summary: format!("Reconciled {repaired} tasks"),
    })
}
fn reconcile_task(
    host: &mut impl Host,
    mut old: Task,
    now: i64,
    runs: &[Value],
    jobs: &[Value],
) -> Result<(), String> {
    if old.value.state.source_version != env!("CARGO_PKG_VERSION") {
        let mut value = old.value.clone();
        value.state.generation = value
            .state
            .generation
            .checked_add(1)
            .ok_or("Task generation exhausted")?;
        value.state.source_version = env!("CARGO_PKG_VERSION").into();
        value.state.pending.clear();
        // Keep an existing overdue occurrence. An already-delivered once task stays completed.
        if value.next_run.is_none()
            && value.draft.enabled
            && value.monitor.is_none()
            && matches!(value.draft.schedule, Schedule::Cron { .. })
        {
            value.next_run = value.draft.schedule.next_after(now)?;
        }
        if value.next_run.is_none()
            && value.draft.enabled
            && let Some(monitor) = &mut value.monitor
        {
            // An interrupted old check counts toward the original finite budget.
            if !old.value.state.pending.is_empty() {
                monitor.remaining = monitor.remaining.saturating_sub(1);
            }
            let next = now
                .checked_add(monitor.interval_seconds)
                .ok_or("Invalid monitor timestamp")?;
            if monitor.remaining > 0 && next < monitor.expires_at {
                value.next_run = Some(next);
            } else {
                value.draft.enabled = false;
            }
        }
        old = save(host, Some(&old), value)?;
    }
    if old
        .value
        .monitor
        .as_ref()
        .is_some_and(|monitor| monitor.expires_at <= now || monitor.remaining <= 0)
        && old.value.draft.enabled
    {
        let mut value = old.value.clone();
        value.draft.enabled = false;
        value.next_run = None;
        old = save(host, Some(&old), value)?;
    }
    // Also repairs a drop after generation invalidation but before cancellation.
    for (capability, records) in [("jobs", jobs), ("runs", runs)] {
        for record in records {
            let Some(due) = record["key"].as_str().and_then(occurrence) else {
                continue;
            };
            if due.task_id != old.id {
                continue;
            }
            if capability == "runs"
                && old.value.next_run == Some(due.due_at)
                && !old
                    .value
                    .state
                    .pending
                    .iter()
                    .any(|pending| Some(pending.id) == record["id"].as_i64())
            {
                record_history(host, old.id, due.due_at, record)?;
            }
            if (!old.value.draft.enabled || due.generation != old.value.state.generation)
                && matches!(
                    record["state"].as_str(),
                    Some("pending" | "leased" | "running" | "blocked" | "waiting")
                )
            {
                host.call(
                    capability,
                    json!({"action":"cancel","id":record["id"],"revision":record["revision"]}),
                )?;
            }
        }
    }
    if old.value.state.deleting {
        collection(
            host,
            "tasks",
            json!({"action":"delete","id":old.id,"revision":old.revision}),
        )?;
        return Ok(());
    }
    old = flush_preflight(host, old)?;
    // A released callback retains its terminal run snapshot after raw-run cleanup.
    // Repair failed delivery through ordinary scoped APIs, then free its queue slot.
    // Never race a pending/leased delivery or reinterpret an unreleased callback.
    let task_id = old.id;
    for job in jobs
        .iter()
        .filter(|job| {
            job["event"] == "task_completed"
                && matches!(
                    job["state"].as_str(),
                    Some("completed" | "failed" | "cancelled" | "expired")
                )
                && job["payload"]["data"]["task_id"].as_i64() == Some(task_id)
                && job["key"]
                    .as_str()
                    .is_some_and(|key| key.starts_with("$run:"))
        })
        .take(2)
    {
        let input: Completed = serde_json::from_value(job["payload"].clone())
            .map_err(|error| format!("Invalid retained completion: {error}"))?;
        let run_id = input.run["id"]
            .as_i64()
            .ok_or("Invalid retained run identity")?;
        if run_id <= 0 || job["key"].as_str() != Some(format!("$run:{run_id}").as_str()) {
            return Err("Retained callback identity does not match its run".into());
        }
        completed(host, input)?;
        old = task(host, old.id)?;
        host.call(
            "jobs",
            json!({"action":"delete","id":job["id"],"revision":job["revision"]}),
        )?;
    }
    if !old.value.draft.enabled {
        return Ok(());
    }
    for run in runs {
        let Some(due) = run["key"].as_str().and_then(occurrence) else {
            continue;
        };
        if due.task_id != old.id
            || due.generation != old.value.state.generation
            || (old.value.next_run != Some(due.due_at)
                && !old
                    .value
                    .state
                    .pending
                    .iter()
                    .any(|pending| Some(pending.id) == run["id"].as_i64()))
        {
            continue;
        }
        if matches!(
            run["state"].as_str(),
            Some("completed" | "failed" | "cancelled" | "interrupted")
        ) {
            completed(
                host,
                Completed {
                    run: run.clone(),
                    data: due,
                },
            )?;
            old = task(host, old.id)?;
        } else if old.value.next_run == Some(due.due_at) {
            let mut value = old.value.clone();
            let id = run["id"].as_i64().ok_or("Invalid recovered run")?;
            if !value.state.pending.iter().any(|pending| pending.id == id) {
                value.state.pending.push(Pending {
                    id,
                    key: run["key"].as_str().ok_or("Invalid recovered key")?.into(),
                    due_at: due.due_at,
                });
            }
            value.next_run = if value.monitor.is_some() {
                None
            } else {
                value.draft.schedule.next_after(now)?
            };
            old = save(host, Some(&old), value)?;
        }
    }
    if let Some(due_at) = old.value.next_run {
        let key = format!("task:{}:{}:{due_at}", old.id, old.value.state.generation);
        for job in jobs
            .iter()
            .filter(|job| job["key"].as_str() == Some(key.as_str()))
        {
            if matches!(
                job["state"].as_str(),
                Some("completed" | "failed" | "cancelled" | "expired")
            ) {
                host.call(
                    "jobs",
                    json!({"action":"delete","id":job["id"],"revision":job["revision"]}),
                )?;
            }
        }
    }
    arm(host, &old)
}
fn record_history(host: &mut impl Host, task: i64, due: i64, run: &Value) -> Result<(), String> {
    let id = run["id"].as_i64().ok_or("Invalid history run")?;
    let state = run["state"].as_str().ok_or("Invalid history state")?;
    let status = match state {
        "pending" => "queued",
        "leased" => "claimed",
        "completed" => "complete",
        other => other,
    };
    collection(
        host,
        "task_runs",
        json!({"action":"create","value":{
            "key":format!("run:{id}"),"task_id":task,"due_at":due,"run_id":id,
            "snapshot":{"status":status,"detail":run["detail"].as_str().unwrap_or(""),
                "session_id":run["session_id"],"message_id":run["message_id"],"permission_id":run["permission_id"]}
        }}),
    )?;
    Ok(())
}
/// Finish journaled failure history before clearing its durable repair marker.
fn flush_preflight(host: &mut impl Host, old: Task) -> Result<Task, String> {
    let Some(failure) = &old.value.state.preflight else {
        return Ok(old);
    };
    collection(
        host,
        "task_runs",
        json!({"action":"create","value":{
            "key":failure.key,"task_id":old.id,"due_at":failure.due_at,"run_id":null,
            "snapshot":{"status":"failed","detail":failure.detail}
        }}),
    )?;
    let mut value = old.value.clone();
    value.state.preflight = None;
    save(host, Some(&old), value)
}
fn preflight_failed(
    host: &mut impl Host,
    old: Task,
    input: &Due,
    now: i64,
    detail: String,
) -> Result<Outcome, String> {
    let mut value = old.value.clone();
    let key = format!("preflight:{}:{}:{}", old.id, input.generation, input.due_at);
    value.state.preflight = Some(PreflightFailure {
        key: key.clone(),
        due_at: input.due_at,
        detail: detail.clone(),
    });
    value.state.last_result = Some(json!({"key":key,"state":"failed","detail":detail}));
    value.next_run = if value.monitor.is_some() {
        value.draft.enabled = false;
        None
    } else {
        value.draft.schedule.next_after(now)?
    };
    let advanced = save(host, Some(&old), value)?;
    let advanced = flush_preflight(host, advanced)?;
    arm(host, &advanced)?;
    Ok(outcome(
        json!({"failed":true}),
        "Task preflight failure recorded",
    ))
}
/// Queue a raw prompt; record prerequisites close the read/edit/submit race.
pub fn due(host: &mut impl Host, input: Due) -> Result<Outcome, String> {
    let Some(old) = tasks(host)?
        .into_iter()
        .find(|task| task.id == input.task_id)
    else {
        return Ok(outcome(
            json!({"ignored":true}),
            "Deleted occurrence ignored",
        ));
    };
    let old = flush_preflight(host, old)?;
    if !old.value.draft.enabled
        || old.value.state.generation != input.generation
        || old.value.next_run != Some(input.due_at)
    {
        if old.value.draft.enabled && old.value.state.generation == input.generation {
            arm(host, &old)?;
        }
        return Ok(outcome(json!({"ignored":true}), "Stale occurrence ignored"));
    }
    let now = clock(host)?;
    if now < input.due_at {
        return Err("Task occurrence is not due yet".into());
    }
    if let Some(monitor) = &old.value.monitor
        && (monitor.remaining <= 0 || monitor.expires_at <= now)
    {
        let mut stopped = old.value.clone();
        stopped.draft.enabled = false;
        stopped.next_run = None;
        save(host, Some(&old), stopped)?;
        return Ok(outcome(json!({"expired":true}), "Monitor expired"));
    }
    let metadata = all::<Conversation>(host, "conversations")?;
    let configuration = collection(host, "configuration", json!({"action":"read","id":1}))?;
    let config: Configuration =
        serde_json::from_value(configuration["records"][0]["value"].clone())
            .map_err(|error| error.to_string())?;
    let default = config.default_model().ok();
    let key = format!("task:{}:{}:{}", old.id, input.generation, input.due_at);
    let selection = conversations::select(&old.value.draft, &metadata, default.as_ref()).and_then(
        |selection| {
            if config
                .servers
                .iter()
                .any(|server| server.id == selection.model.server_id && server.enabled)
            {
                Ok(selection)
            } else {
                Err("The configured model server is unavailable for this task".into())
            }
        },
    );
    let response = match selection {
        Ok(selection) => host.call("runs",json!({"action":"submit","key":key,"prompt":old.value.draft.prompt,
        "target":selection.target,"model":selection.model,
        "prerequisites":[{"capability":"collections","collection":"tasks","id":old.id,"revision":old.revision}],
        "completion":{"event":"task_completed","payload":{"task_id":old.id,"generation":input.generation,"due_at":input.due_at}}}))?,
        Err(detail) => {
            // A lost acknowledgement may have queued this occurrence before its
            // conversation/configuration changed. Preserve that accepted work.
            if let Some(run) = work(host, "runs")?.into_iter().find(|run| run["key"] == key) {
                json!({"runs":[run]})
            } else {
                return preflight_failed(host, old, &input, now, detail);
            }
        }
    };
    let run = &response["runs"][0];
    let id = run["id"].as_i64().ok_or("No queued run returned")?;
    record_history(host, old.id, input.due_at, run)?;
    let mut value = old.value.clone();
    if !value.state.pending.iter().any(|run| run.id == id) {
        value.state.pending.push(Pending {
            id,
            key,
            due_at: input.due_at,
        });
    }
    value.next_run = if value.monitor.is_some() {
        None
    } else {
        value.draft.schedule.next_after(now)?
    };
    let advanced = save(host, Some(&old), value)?;
    arm(host, &advanced)?;
    Ok(outcome(response, "Scheduled prompt queued"))
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Completed {
    pub run: Value,
    pub data: Due,
}
pub fn completed(host: &mut impl Host, input: Completed) -> Result<Outcome, String> {
    let Some(old) = tasks(host)?
        .into_iter()
        .find(|task| task.id == input.data.task_id)
    else {
        return Ok(outcome(json!({"ignored":true}), "Deleted result ignored"));
    };
    let expected_key = format!(
        "task:{}:{}:{}",
        old.id, input.data.generation, input.data.due_at
    );
    if input.run["key"].as_str() != Some(expected_key.as_str()) {
        return Err("Run completion key does not match occurrence".into());
    }
    let state = input.run["state"]
        .as_str()
        .ok_or("Invalid completion state")?;
    if !matches!(state, "completed" | "failed" | "cancelled" | "interrupted") {
        return Err("Completion run is not terminal".into());
    }
    record_history(host, old.id, input.data.due_at, &input.run)?;
    if !old.value.draft.enabled || old.value.state.generation != input.data.generation {
        return Ok(outcome(json!({"ignored":true}), "Stale result ignored"));
    }
    let run_id = input.run["id"].as_i64().ok_or("Invalid completion run")?;
    if old
        .value
        .state
        .last_result
        .as_ref()
        .is_some_and(|last| last["id"].as_i64() == Some(run_id))
    {
        arm(host, &old)?;
        return Ok(outcome(json!({"ignored":true}), "Result already recorded"));
    }
    if !old.value.state.pending.iter().any(|run| run.id == run_id)
        && old.value.next_run != Some(input.data.due_at)
    {
        arm(host, &old)?;
        return Ok(outcome(json!({"ignored":true}), "Prior result ignored"));
    }
    let now = clock(host)?;
    let mut value = old.value.clone();
    value.state.pending.retain(|run| run.id != run_id);
    if !value
        .state
        .last_result
        .as_ref()
        .is_some_and(|prior| prior["id"].as_i64().is_some_and(|id| id > run_id))
    {
        value.state.last_result = Some(input.run.clone());
    }
    if let Some(monitor) = &mut value.monitor {
        monitor.remaining = monitor.remaining.saturating_sub(1);
        let next = now
            .checked_add(monitor.interval_seconds)
            .ok_or("Invalid monitor timestamp")?;
        if state == "completed" && monitor.remaining > 0 && next < monitor.expires_at {
            value.next_run = Some(next);
        } else {
            value.next_run = None;
            value.draft.enabled = false;
        }
    } else if value.next_run == Some(input.data.due_at) {
        // Completion can repair a crash after submit but before occurrence advancement.
        value.next_run = value.draft.schedule.next_after(now)?;
    }
    let advanced = save(host, Some(&old), value)?;
    arm(host, &advanced)?;
    Ok(outcome(json!({"recorded":true}), "Task result recorded"))
}

use openwebide_plugin_sdk::serde_json::{self, Value, json};
use scheduling_plugin::{
    schedule::{Draft, Schedule, SessionTarget},
    service::{self, Completed, Due, Host},
};
use std::collections::BTreeMap;
#[derive(Default)]
struct Fixture {
    now: i64,
    tasks: BTreeMap<i64, Value>,
    jobs: BTreeMap<i64, Value>,
    runs: BTreeMap<i64, Value>,
    job_id: i64,
    run_id: i64,
    calls: Vec<(String, Value)>,
    config: Value,
    conversations: Vec<Value>,
    fail_arm: bool,
    fail_update: Option<i64>,
    fail_history: bool,
    fail_history_task: Option<i64>,
    enforce_history_limit: bool,
    history: BTreeMap<String, Value>,
    history_id: i64,
    recovery: Option<Value>,
    fail_recovery_write: bool,
}
impl Fixture {
    fn new() -> Self {
        Self {
            now: 100,
            config: json!({"primary":{"server_id":1,"model":"current default"},"default_connection":null,"servers":[{"id":1,"model":"server model","enabled":true}]}),
            conversations: vec![
                json!({"id":1,"value":{"origin":true,"archived":false,"last_activity":90,"model_override":{"connection_id":1,"model":"session model"},"connection":null}}),
            ],
            ..Self::default()
        }
    }
    fn create(&mut self, draft: Draft) -> Value {
        let result = service::execute(self, "schedule_create", json!({"draft":draft})).unwrap();
        serde_json::from_str::<Value>(&result.content).unwrap()[0].clone()
    }
    fn run(&self) -> Value {
        self.runs.values().last().unwrap().clone()
    }
    fn next(&self) -> Option<i64> {
        self.tasks[&1]["value"]["next_run"].as_i64()
    }
    fn finish(&mut self, run: Value) -> service::Completed {
        Completed {
            data: serde_json::from_value(run["request"]["completion"]["payload"].clone()).unwrap(),
            run,
        }
    }
}
impl Host for Fixture {
    fn call(&mut self, capability: &str, input: Value) -> Result<Value, String> {
        self.calls.push((capability.into(), input.clone()));
        match capability {
            "clock" => Ok(json!({"unix_seconds":self.now})),
            "completion" => Err("Model is unavailable".into()),
            "records" => {
                assert_eq!(input["collection"], "recovery");
                let op = &input["operation"];
                if op["action"] != "list" && self.fail_recovery_write {
                    return Err("Recovery cursor write unavailable".into());
                }
                match op["action"].as_str().unwrap() {
                    "list" => (),
                    "create" => {
                        self.recovery = Some(json!({"id":1,"revision":1,"value":op["value"]}))
                    }
                    "update" => {
                        let old = self.recovery.as_ref().ok_or("Missing recovery record")?;
                        if old["revision"] != op["revision"] {
                            return Err("Recovery conflict".into());
                        }
                        self.recovery = Some(
                            json!({"id":1,"revision":old["revision"].as_i64().unwrap()+1,"value":op["value"]}),
                        );
                    }
                    _ => panic!("Unexpected recovery operation"),
                }
                Ok(json!({"records":self.recovery.iter().collect::<Vec<_>>(),"next":null}))
            }
            "collections" => {
                let operation = &input["operation"];
                let action = operation["action"].as_str().unwrap();
                match input["collection"].as_str().unwrap() {
                    "configuration" => Ok(
                        json!({"records":[{"id":1,"revision":1,"value":self.config}],"next":null}),
                    ),
                    "conversations" => Ok(json!({"records":self.conversations,"next":null})),
                    "task_runs" => {
                        if action == "list" {
                            let after = operation["after"].as_i64().unwrap_or(0);
                            let mut records: Vec<_> = self
                                .history
                                .values()
                                .filter(|row| row["id"].as_i64().unwrap() > after)
                                .cloned()
                                .collect();
                            records.sort_by_key(|row| row["id"].as_i64().unwrap());
                            let next = (records.len() > 32).then(|| records[31]["id"].clone());
                            records.truncate(32);
                            return Ok(json!({"records":records,"next":next}));
                        }
                        if action == "delete" {
                            let key = self
                                .history
                                .iter()
                                .find(|(_, row)| row["id"] == operation["id"])
                                .map(|(key, _)| key.clone())
                                .ok_or("Missing history")?;
                            let row = &self.history[&key];
                            if row["revision"] != operation["revision"]
                                || row["value"]["editable"] != true
                                || !matches!(
                                    row["value"]["snapshot"]["status"].as_str(),
                                    Some(
                                        "complete"
                                            | "failed"
                                            | "cancelled"
                                            | "expired"
                                            | "interrupted"
                                    )
                                )
                            {
                                return Err("History cannot be deleted".into());
                            }
                            self.history.remove(&key);
                            return Ok(json!({"records":[],"next":null}));
                        }
                        assert_eq!(action, "create");
                        if self.fail_history
                            || self.fail_history_task.is_some_and(|task| {
                                operation["value"]["task_id"].as_i64() == Some(task)
                            })
                        {
                            return Err("History write unavailable".into());
                        }
                        let mut value = operation["value"].clone();
                        value["editable"] = json!(true);
                        let key = value["key"].as_str().unwrap().to_owned();
                        if self.enforce_history_limit
                            && self.history.len() >= 1000
                            && !self.history.contains_key(&key)
                        {
                            return Err(
                                "Task history holds at most 1,000 entries in this scope".into()
                            );
                        }
                        if !self.history.contains_key(&key) {
                            self.history_id += 1;
                        }
                        let index = self.history_id;
                        let record = self
                            .history
                            .entry(key)
                            .or_insert_with(|| json!({"id":index,"revision":1,"value":value}));
                        Ok(json!({"records":[record],"next":null}))
                    }
                    "tasks" => {
                        let id = operation["id"].as_i64().unwrap_or(0);
                        let mut selected = None;
                        match action {
                            "create" => {
                                let id = self.tasks.keys().last().copied().unwrap_or(0) + 1;
                                self.tasks.insert(
                                    id,
                                    json!({"id":id,"revision":1,"value":operation["value"]}),
                                );
                                selected = Some(id);
                            }
                            "update" | "delete" => {
                                if action == "update" && self.fail_update == Some(id) {
                                    return Err("Revision conflict".into());
                                }
                                let current = self.tasks.get(&id).ok_or("Missing task")?;
                                if current["revision"] != operation["revision"] {
                                    return Err("Revision conflict".into());
                                }
                                let revision = current["revision"].as_i64().unwrap() + 1;
                                if action == "delete" {
                                    self.tasks.remove(&id);
                                } else {
                                    self.tasks.insert(id,json!({"id":id,"revision":revision,"value":operation["value"]}));
                                    selected = Some(id);
                                }
                            }
                            "read" => selected = Some(id),
                            "list" => (),
                            _ => panic!("Unsupported operation"),
                        }
                        let records = if let Some(id) = selected {
                            vec![self.tasks.get(&id).ok_or("Missing task")?.clone()]
                        } else if action == "delete" {
                            vec![]
                        } else {
                            self.tasks.values().cloned().collect()
                        };
                        Ok(json!({"records":records,"next":null}))
                    }
                    _ => panic!("Unexpected collection"),
                }
            }
            "jobs" | "runs" => {
                let action = input["action"].as_str().unwrap();
                let field = if capability == "jobs" { "jobs" } else { "runs" };
                if action == "submit" {
                    for guard in input["prerequisites"].as_array().unwrap() {
                        if self.tasks[&guard["id"].as_i64().unwrap()]["revision"]
                            != guard["revision"]
                        {
                            return Err("Stale prerequisite".into());
                        }
                    }
                }
                let records = if capability == "jobs" {
                    &mut self.jobs
                } else {
                    &mut self.runs
                };
                match action {
                    "schedule" | "submit" => {
                        if capability == "jobs" && self.fail_arm {
                            return Err("Job queue unavailable".into());
                        }
                        if let Some(existing) = records
                            .values()
                            .find(|record| record["key"] == input["key"])
                        {
                            return Ok(json!({field:[existing],"next_after":null}));
                        }
                        let counter = if capability == "jobs" {
                            &mut self.job_id
                        } else {
                            &mut self.run_id
                        };
                        *counter =
                            (*counter + 1).max(records.keys().last().copied().unwrap_or(0) + 1);
                        let id = *counter;
                        let record = json!({"id":id,"revision":1,"key":input["key"],"state":"pending",
                            "event":input["event"],"payload":input["payload"],"request":input});
                        records.insert(id, record.clone());
                        Ok(json!({field:[record],"next_after":null}))
                    }
                    "list" => {
                        Ok(json!({field:records.values().collect::<Vec<_>>(),"next_after":null}))
                    }
                    "delete" => {
                        let id = input["id"].as_i64().unwrap();
                        let record = records.get(&id).ok_or("Missing work")?;
                        if record["revision"] != input["revision"] {
                            return Err("Revision conflict".into());
                        }
                        records.remove(&id);
                        Ok(json!({field:[],"next_after":null}))
                    }
                    "cancel" => {
                        let record = records
                            .get_mut(&input["id"].as_i64().unwrap())
                            .ok_or("Missing work")?;
                        record["state"] = json!("cancelled");
                        record["revision"] = json!(record["revision"].as_i64().unwrap() + 1);
                        Ok(json!({field:[record],"next_after":null}))
                    }
                    _ => panic!("Unsupported work operation"),
                }
            }
            _ => panic!("Unexpected host capability: {capability}"),
        }
    }
}
fn draft(schedule: Schedule, target: SessionTarget) -> Draft {
    Draft {
        session_target: target,
        session_id: 0,
        title: String::new(),
        auto_title: true,
        prompt: "Check the latest build".into(),
        schedule,
        enabled: true,
        model: None,
    }
}
#[test]
fn enablement_preserves_titles_and_rejects_stale_and_elapsed_once_resumes() {
    let mut host = Fixture::new();
    host.create(draft(Schedule::Once { at: 105 }, SessionTarget::Existing));
    let title = host.tasks[&1]["value"]["draft"]["title"].clone();
    host.calls.clear();
    service::execute(
        &mut host,
        "schedule_set_enabled",
        json!({"id":1,"revision":1,"enabled":false}),
    )
    .unwrap();
    assert_eq!(host.tasks[&1]["value"]["draft"]["title"], title);
    assert_eq!(host.tasks[&1]["value"]["draft"]["auto_title"], true);
    assert_eq!(host.next(), None);
    assert!(
        !host
            .calls
            .iter()
            .any(|(capability, _)| capability == "completion")
    );
    assert!(
        service::execute(
            &mut host,
            "schedule_set_enabled",
            json!({"id":1,"revision":1,"enabled":true})
        )
        .is_err()
    );
    service::execute(
        &mut host,
        "schedule_set_enabled",
        json!({"id":1,"revision":2,"enabled":true}),
    )
    .unwrap();
    assert_eq!(host.next(), Some(105));
    host.now = 110;
    service::execute(
        &mut host,
        "schedule_set_enabled",
        json!({"id":1,"revision":3,"enabled":false}),
    )
    .unwrap();
    assert!(
        service::execute(
            &mut host,
            "schedule_set_enabled",
            json!({"id":1,"revision":4,"enabled":true})
        )
        .is_err()
    );
    assert_eq!(host.tasks[&1]["revision"], 4);
}

